package com.portfolio.assetory.refund;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import com.portfolio.assetory.access.repository.ProductAccessRepository;import com.portfolio.assetory.global.auth.CurrentUserId;import com.portfolio.assetory.global.exception.*;import com.portfolio.assetory.global.response.ApiResponse;import com.portfolio.assetory.order.domain.*;import com.portfolio.assetory.order.repository.OrderItemRepository;import com.portfolio.assetory.payment.repository.PaymentRepository;
@RestController @RequestMapping("/api/refunds") public class RefundController{private final RefundService service;public RefundController(RefundService service){this.service=service;}@PostMapping public ResponseEntity<ApiResponse<Response>> request(@CurrentUserId Long u,@Valid @RequestBody Request r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(service.request(u,r)));}@PatchMapping("/{id}/cancel")public ResponseEntity<ApiResponse<Response>> cancel(@CurrentUserId Long u,@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success(service.cancel(u,id)));}@GetMapping public ResponseEntity<ApiResponse<ListResponse>> list(@CurrentUserId Long u,@RequestParam(defaultValue="0")int p,@RequestParam(defaultValue="20")int s){return ResponseEntity.ok(ApiResponse.success(service.listBuyer(u,p,s)));}@GetMapping("/{id}")public ResponseEntity<ApiResponse<Response>> detail(@CurrentUserId Long u,@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success(service.buyerDetail(u,id)));}public record Request(@NotNull Long orderItemId,@NotBlank @Size(min=10,max=1000)String reason){}public record SellerProcessRequest(@Size(max=1000)String sellerMessage){}public record RejectRequest(@NotBlank @Size(min=10,max=1000)String rejectionReason){}public record Response(Long refundId,Long orderItemId,Long productId,String productName,BigDecimal refundAmount,String reason,String status,String sellerMessage,String rejectionReason,LocalDateTime requestedAt,LocalDateTime processedAt,LocalDateTime completedAt,LocalDateTime canceledAt){static Response from(Refund r){var i=r.getOrderItem();return new Response(r.getId(),i.getId(),i.getProduct().getId(),i.getProductName(),r.getRefundAmount(),r.getReason(),r.getStatus().name(),r.getSellerMessage(),r.getRejectionReason(),r.getRequestedAt(),r.getProcessedAt(),r.getCompletedAt(),r.getCanceledAt());}}public record ListResponse(List<Response> refunds,int page,int totalPages){}}
@RestController @RequestMapping("/api/seller/refunds")class SellerRefundController{private final RefundService service;SellerRefundController(RefundService s){service=s;}@GetMapping public ResponseEntity<ApiResponse<RefundController.ListResponse>> list(@CurrentUserId Long u,@RequestParam(defaultValue="0")int p,@RequestParam(defaultValue="20")int s){return ResponseEntity.ok(ApiResponse.success(service.listSeller(u,p,s)));}@GetMapping("/{id}")public ResponseEntity<ApiResponse<RefundController.Response>> detail(@CurrentUserId Long u,@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success(service.sellerDetail(u,id)));}@PatchMapping("/{id}/approve")public ResponseEntity<ApiResponse<RefundController.Response>> approve(@CurrentUserId Long u,@PathVariable Long id,@Valid @RequestBody(required=false)RefundController.SellerProcessRequest r){return ResponseEntity.ok(ApiResponse.success(service.approve(u,id,r==null?null:r.sellerMessage())));}@PatchMapping("/{id}/reject")public ResponseEntity<ApiResponse<RefundController.Response>> reject(@CurrentUserId Long u,@PathVariable Long id,@Valid @RequestBody RefundController.RejectRequest r){return ResponseEntity.ok(ApiResponse.success(service.reject(u,id,r.rejectionReason())));}@PatchMapping("/{id}/complete")public ResponseEntity<ApiResponse<RefundController.Response>> complete(@CurrentUserId Long u,@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success(service.complete(u,id)));}}
@Service @Transactional class RefundService{private final OrderItemRepository items;private final RefundRepository refunds;private final ProductAccessRepository accesses;RefundService(OrderItemRepository i,RefundRepository r,ProductAccessRepository a,PaymentRepository ignored){items=i;refunds=r;accesses=a;}RefundController.Response request(Long u,RefundController.Request q){var i=items.findById(q.orderItemId()).orElseThrow(()->new BusinessException(ErrorCode.ORDER_NOT_FOUND));if(!i.getOrder().getBuyer().getId().equals(u))throw new BusinessException(ErrorCode.FORBIDDEN);if(refunds.existsByOrderItemId(i.getId()))throw new BusinessException(ErrorCode.REFUND_ALREADY_EXISTS);if(i.getOrder().getStatus()!=OrderStatus.PAID)throw new BusinessException(ErrorCode.INVALID_REFUND_STATUS);i.getOrder().markRefundRequested();return RefundController.Response.from(refunds.save(Refund.request(i,q.reason())));}RefundController.Response cancel(Long u,Long id){var r=refunds.findForBuyer(id,u).orElseThrow(()->new BusinessException(ErrorCode.REFUND_NOT_FOUND));if(r.getStatus()!=RefundStatus.REQUESTED)throw new BusinessException(ErrorCode.INVALID_REFUND_STATUS);r.cancel();r.getOrderItem().getOrder().restorePaid();return RefundController.Response.from(r);}RefundController.Response approve(Long u,Long id,String m){var r=seller(id,u);if(r.getStatus()!=RefundStatus.REQUESTED)throw new BusinessException(ErrorCode.INVALID_REFUND_STATUS);r.approve(m);r.getOrderItem().getOrder().markRefundApproved();return RefundController.Response.from(r);}RefundController.Response reject(Long u,Long id,String m){var r=seller(id,u);if(r.getStatus()!=RefundStatus.REQUESTED)throw new BusinessException(ErrorCode.INVALID_REFUND_STATUS);r.reject(m);r.getOrderItem().getOrder().markRefundRejected();return RefundController.Response.from(r);}RefundController.Response complete(Long u,Long id){var r=seller(id,u);if(r.getStatus()!=RefundStatus.APPROVED)throw new BusinessException(ErrorCode.INVALID_REFUND_STATUS);r.complete();r.getOrderItem().getOrder().markRefunded();accesses.findByOrderItemId(r.getOrderItem().getId()).ifPresent(a->a.revoke());return RefundController.Response.from(r);}RefundController.Response buyerDetail(Long u,Long id){return RefundController.Response.from(refunds.findForBuyer(id,u).orElseThrow(()->new BusinessException(ErrorCode.REFUND_NOT_FOUND)));}RefundController.Response sellerDetail(Long u,Long id){return RefundController.Response.from(seller(id,u));}RefundController.ListResponse listBuyer(Long u,int p,int s){return list(refunds.findAllForBuyer(u,page(p,s)));}RefundController.ListResponse listSeller(Long u,int p,int s){return list(refunds.findAllForSeller(u,page(p,s)));}private Pageable page(int p,int s){if(p<0||s<1||s>100)throw new BusinessException(ErrorCode.INVALID_INPUT);return PageRequest.of(p,s,Sort.by(Sort.Direction.DESC,"requestedAt"));}private RefundController.ListResponse list(Page<Refund> p){return new RefundController.ListResponse(p.getContent().stream().map(RefundController.Response::from).toList(),p.getNumber(),p.getTotalPages());}private Refund seller(Long id,Long u){return refunds.findForSeller(id,u).orElseThrow(()->new BusinessException(ErrorCode.REFUND_NOT_FOUND));}}
